INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_020_M02_S01', 'Free/forced convection', '1', 'Free/forced convection: Heat transfer between a surface and moving fluid driven respectively by buoyancy or by externally imposed fluid motion. In Convection, the focus is on natural/free convection, forced convection, boundary layers, dimensionless correlations and heat-transfer coefficients.', 'SSD_FREE_FORCED_CONVECTION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_020_M03_S01', 'Blackbody radiation', '1', 'Blackbody radiation: Thermal radiation idealization for a surface that absorbs all incident radiation and emits the maximum possible radiation at a given temperature. In Radiation, the focus is on blackbody emissive power, Stefan-Boltzmann law, spectral distribution and radiative exchange assumptions.', 'SSD_BLACKBODY_RADIATION', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_020_M04_S01', 'Log Mean Temperature Difference (LMTD)', '1', 'LMTD: Log-mean temperature difference, a mean temperature-driving-force measure used in heat-exchanger analysis when the temperature difference varies along the exchanger. In Heat Exchangers, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_LMTD', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_020_M05_S01', 'Mass diffusion and transfer coefficients', '1', 'Mass diffusion and transfer coefficients: Transport of chemical species caused by concentration gradients and the coefficients used to relate mass-transfer flux to a driving concentration difference. In Mass Transfer, the focus is on fickian diffusion, concentration gradients, molecular diffusivity, convective mass transfer and dimensionless correlations.', 'SSD_MASS_DIFFUSION_AND_TRANSFER_COEFFICIENTS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_021_M01_S01', 'Flywheels', '1', 'Flywheels: Rotating mechanical energy-storage elements that reduce cyclic speed fluctuations by storing and releasing kinetic energy. In Dynamic Force Analysis, the focus is on energy fluctuation, moment of inertia, coefficient of speed fluctuation and angular velocity.', 'SSD_FLYWHEELS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_021_M02_S01', 'Static and dynamic balancing', '1', 'Static and dynamic balancing: Procedures for reducing unbalanced forces and moments in rotating or reciprocating machinery. In Balancing, the focus is on mass distribution, centrifugal forces, static balance, couple balance, correction planes and balancing procedures.', 'SSD_STATIC_AND_DYNAMIC_BALANCING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_021_M03_S01', 'Natural frequency', '1', 'Natural frequency refers to a characteristic frequency at which a system can oscillate freely after a disturbance in the absence of sustained external excitation and damping effects. In Free Vibration, the focus is on single/multi-degree systems, stiffness, mass, damping influence and mode shapes.', 'SSD_NATURAL_FREQUENCY', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_021_M04_S01', 'Resonance', '1', 'Resonance refers to a condition in which forced vibration response becomes large when excitation frequency approaches an appropriate natural frequency of the system. In Forced Vibration, the focus is on frequency response, damping, natural frequency, amplitude and phase behaviour.', 'SSD_RESONANCE', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_021_M05_S01', 'Governor and gyroscope principles', '1', 'Governor and gyroscope principles: Rotational-mechanics principles represented by governors for speed regulation and gyroscopes for angular-momentum-based orientation and reaction effects. In Governors & Gyroscopes, the focus is on governor equilibrium/speed regulation; gyroscopic moment, precession and angular momentum.', 'SSD_GOVERNOR_AND_GYROSCOPE_PRINCIPLES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_022_M01_S01', 'Sand casting', '1', 'Sand casting refers to a metal casting process in which molten metal is poured into a mould cavity formed in compacted sand. In Casting, the focus is on pattern, moulding sand, gating/riser system, solidification, defects and post-casting finishing.', 'SSD_SAND_CASTING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_022_M02_S01', 'Forging', '1', 'Forging refers to a manufacturing process that plastically deforms metal using compressive forces to produce a desired shape and properties. In Metal Forming, the focus is on open/closed-die forging, temperature, deformation, grain flow, tooling and defects.', 'SSD_FORGING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_022_M03_S01', 'Arc welding', '1', 'Arc welding refers to a fusion welding process in which an electric arc supplies heat to melt and join materials, with or without filler metal. In Joining Processes, the focus is on arc generation, electrodes, shielding, heat input, joint preparation, weld defects and safety.', 'SSD_ARC_WELDING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_022_M04_S01', 'Lathe operations', '1', 'Lathe operations: Material-removal operations performed on a lathe in which a workpiece rotates while a cutting tool removes material. In Machining, the focus is on turning, facing, tapering, threading, boring, cutting speed, feed, depth of cut and tool geometry.', 'SSD_LATHE_OPERATIONS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_022_M05_S01', 'Electrical discharge machining', '1', 'Electrical discharge machining refers to a non-contact machining process that removes electrically conductive workpiece material through controlled electrical discharges in a dielectric medium. In Non-traditional Machining, the focus is on electrode/workpiece gap, spark energy, dielectric, material removal rate, surface finish and tool wear.', 'SSD_ELECTRICAL_DISCHARGE_MACHINING', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_023_M01_S01', 'Von Mises', '1', 'Von Mises refers to the von Mises yield criterion predicts yielding of ductile isotropic materials from the distortion-energy component of the stress state. In Failure Theories, the focus is on equivalent von Mises stress, multiaxial stress states, yield strength comparison and ductile-metal applicability.', 'SSD_VON_MISES', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_023_M02_S01', 'Goodman diagram', '1', 'Goodman diagram refers to a fatigue-design diagram relating alternating stress and mean stress to an endurance-strength criterion, commonly using a linear Goodman relation. In Fatigue Design, the focus is on mean stress, alternating stress, endurance strength, ultimate strength and safety factors.', 'SSD_GOODMAN_DIAGRAM', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_023_M03_S01', 'Shaft and key design', '1', 'Shaft and key design: Design of rotating shafts and keys to transmit torque while satisfying strength, stiffness, fatigue and connection requirements. In Shafts & Keys, the focus is on torsional/bending stresses, diameter, key dimensions, stress concentrations, deflection and torque transmission.', 'SSD_SHAFT_AND_KEY_DESIGN', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_023_M04_S01', 'Journal bearings', '1', 'Journal bearings: Bearings that support a rotating shaft through sliding contact, commonly separated by a lubricating film under hydrodynamic or related regimes. In Springs & Bearings, the focus is on bearing pressure, viscosity, clearance, Sommerfeld-type parameters, lubrication regime, friction and heat generation.', 'SSD_JOURNAL_BEARINGS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_023_M05_S01', 'Gear design fundamentals', '1', 'Gear design fundamentals: Principles used to select and proportion gears for transmitting motion and torque while satisfying strength, wear, accuracy and service-life requirements. In Gears, the focus is on gear geometry, module/diametral pitch, tooth forces, bending/contact stress, ratios and failure modes.', 'SSD_GEAR_DESIGN_FUNDAMENTALS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_024_M01_S01', 'Laplace transforms', '1', 'Laplace transforms refers to an integral transform that maps suitable time-domain functions to an algebraic function of a complex variable and is widely used to analyze linear dynamic systems. In System Modeling, the focus is on transform definition, properties, inverse transform, poles/zeros and differential-equation solution.', 'SSD_LAPLACE_TRANSFORMS', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_024_M02_S01', 'Time-domain response', '1', 'Time-domain response refers to the temporal output behaviour of a dynamic system following an input, disturbance or initial condition. In Time Domain Analysis, the focus is on transient and steady-state response, rise time, settling time, overshoot, damping and natural frequency.', 'SSD_TIME_DOMAIN_RESPONSE', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_024_M03_S01', 'Routh-Hurwitz and Nyquist criteria', '1', 'Routh-Hurwitz and Nyquist criteria: Frequency- or polynomial-domain stability-analysis methods used to determine whether a feedback system has unstable poles or encirclements associated with closed-loop instability. In Stability, the focus is on routh array, characteristic polynomial, Nyquist plot, encirclement criterion and open-loop/closed-loop relationships.', 'SSD_ROUTH_HURWITZ_AND_NYQUIST_CRITERIA', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_024_M04_S01', 'Bode plot', '1', 'Bode plot refers to a logarithmic magnitude-and-phase representation of a system''s frequency response as a function of frequency. In Frequency Domain Analysis, the focus is on magnitude in decibels, phase, corner frequencies, asymptotic construction and gain/phase margins.', 'SSD_BODE_PLOT', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_024_M05_S01', 'PID control', '1', 'PID control: Feedback control using proportional, integral, and derivative actions to regulate a process variable based on the control error. In Controller Design, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_PID_CONTROL', 'Semantically_Audited', 'Active', '1.0'), ('SUB_COURSE_025_M1_S1', 'agents and environments', '1', 'agents and environments: agents and environments in Artificial Intelligence concerns the interaction between an intelligent agent and the environment through percepts, actions, state transitions, and performance measures. In Intelligent Agents, the focus is on the analysis, design, implementation, interpretation, or evaluation of agents and environments within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context.', 'SSD_COURSE_025_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M1_S2', 'rational action', '2', 'rational action: rational action in Artificial Intelligence concerns the selection of actions that maximize expected performance given the agent''s percept history, knowledge, and available actions. In Intelligent Agents, the focus is on the analysis, design, implementation, interpretation, or evaluation of rational action within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context.', 'SSD_COURSE_025_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M1_S3', 'agent architectures', '3', 'agent architectures: agent architectures in Artificial Intelligence concerns the computational organization of sensing, internal state, reasoning, learning, and action used to implement an intelligent agent. In Intelligent Agents, the focus is on the analysis, design, implementation, interpretation, or evaluation of agent architectures within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context.', 'SSD_COURSE_025_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M1_S4', 'utility and performance measures', '4', 'utility and performance measures: utility and performance measures in Artificial Intelligence concerns formal measures used to represent preferences or assess how effectively an agent achieves its specified objectives. In Intelligent Agents, the focus is on the analysis, design, implementation, interpretation, or evaluation of utility and performance measures within Artificial Intelligence, particularly where the Intelligent Agents module establishes its technical context.', 'SSD_COURSE_025_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M2_S1', 'state-space formulation', '1', 'state-space formulation: state-space formulation in Artificial Intelligence concerns the representation of a problem as states, actions or operators, an initial state, goal conditions, and transition relationships. In Problem Solving and Search, the focus is on the analysis, design, implementation, interpretation, or evaluation of state-space formulation within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'SSD_COURSE_025_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M2_S2', 'uninformed search', '2', 'uninformed search: uninformed search in Artificial Intelligence concerns search strategies that use problem structure such as depth, cost, or breadth without heuristic estimates of distance to a goal. In Problem Solving and Search, the focus is on the analysis, design, implementation, interpretation, or evaluation of uninformed search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'SSD_COURSE_025_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M2_S3', 'heuristic search', '3', 'heuristic search: heuristic search in Artificial Intelligence concerns search strategies that use an estimate of remaining cost or distance to guide exploration toward promising states. In Problem Solving and Search, the focus is on the analysis, design, implementation, interpretation, or evaluation of heuristic search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'SSD_COURSE_025_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M2_S4', 'local search', '4', 'local search: local search in Artificial Intelligence concerns iterative optimization or search methods that maintain one or a small number of candidate states and improve them using neighbourhood information. In Problem Solving and Search, the focus is on the analysis, design, implementation, interpretation, or evaluation of local search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'SSD_COURSE_025_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M2_S5', 'adversarial search', '5', 'adversarial search: adversarial search in Artificial Intelligence concerns search for decision-making in competitive environments where an agent must account for an opposing agent''s actions, typically using minimax-style reasoning. In Problem Solving and Search, the focus is on the analysis, design, implementation, interpretation, or evaluation of adversarial search within Artificial Intelligence, particularly where the Problem Solving and Search module establishes its technical context.', 'SSD_COURSE_025_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M3_S1', 'propositional logic', '1', 'propositional logic: propositional logic in Artificial Intelligence concerns a formal logic in which propositions are represented by Boolean-valued symbols and combined with logical connectives to support deduction. In Knowledge Representation and Reasoning, the focus is on the analysis, design, implementation, interpretation, or evaluation of propositional logic within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'SSD_COURSE_025_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M3_S2', 'first-order logic', '2', 'first-order logic: first-order logic in Artificial Intelligence concerns a predicate logic that represents objects, properties, and relations using predicates, variables, quantifiers, and logical connectives. In Knowledge Representation and Reasoning, the focus is on the analysis, design, implementation, interpretation, or evaluation of first-order logic within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'SSD_COURSE_025_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M3_S3', 'ontologies', '3', 'ontologies: ontologies in Artificial Intelligence concerns formal specifications of concepts, relationships, constraints, and axioms within a domain for shared semantic representation and automated reasoning. In Knowledge Representation and Reasoning, the focus is on the analysis, design, implementation, interpretation, or evaluation of ontologies within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'SSD_COURSE_025_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M3_S4', 'knowledge graphs', '4', 'knowledge graphs: knowledge graphs in Artificial Intelligence concerns graph-based representations in which entities and relations are represented as nodes and edges to support semantic integration, querying, and inference. In Knowledge Representation and Reasoning, the focus is on the analysis, design, implementation, interpretation, or evaluation of knowledge graphs within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'SSD_COURSE_025_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M3_S5', 'inference', '5', 'inference: inference in Artificial Intelligence concerns the derivation of conclusions from represented facts, rules, models, or observations using a specified reasoning procedure. In Knowledge Representation and Reasoning, the focus is on the analysis, design, implementation, interpretation, or evaluation of inference within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'SSD_COURSE_025_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M3_S6', 'reasoning under uncertainty', '6', 'reasoning under uncertainty: reasoning under uncertainty in Artificial Intelligence concerns methods for representing incomplete or uncertain knowledge and deriving conclusions when truth values, probabilities, or evidence are not fully determined. In Knowledge Representation and Reasoning, the focus is on the analysis, design, implementation, interpretation, or evaluation of reasoning under uncertainty within Artificial Intelligence, particularly where the Knowledge Representation and Reasoning module establishes its technical context.', 'SSD_COURSE_025_M3_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M4_S1', 'classical planning', '1', 'classical planning: Planning in which actions have known preconditions and effects and a plan is a sequence of actions that achieves specified goals. In Planning and Decision Making, the focus is on the analysis, design, implementation, interpretation, or evaluation of classical planning within Artificial Intelligence, particularly where the Planning and Decision Making module establishes its technical context.', 'SSD_COURSE_025_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M4_S2', 'partial-order planning', '2', 'partial-order planning: Planning that represents only the ordering constraints required between actions, allowing independent actions to remain unordered. In Planning and Decision Making, the focus is on the analysis, design, implementation, interpretation, or evaluation of partial-order planning within Artificial Intelligence, particularly where the Planning and Decision Making module establishes its technical context.', 'SSD_COURSE_025_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M4_S3', 'probabilistic decision making', '3', 'probabilistic decision making: Choosing actions by comparing their expected outcomes when states, observations, or outcomes are uncertain. In Planning and Decision Making, the focus is on the analysis, design, implementation, interpretation, or evaluation of probabilistic decision making within Artificial Intelligence, particularly where the Planning and Decision Making module establishes its technical context.', 'SSD_COURSE_025_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M4_S4', 'Markov decision processes', '4', 'Markov decision processes refers to a model of sequential decisions in which the next state depends on the current state and chosen action. In Planning and Decision Making, the focus is on the analysis, design, implementation, interpretation, or evaluation of Markov decision processes within Artificial Intelligence, particularly where the Planning and Decision Making module establishes its technical context.', 'SSD_COURSE_025_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M4_S5', 'sequential decision making', '5', 'sequential decision making: Selecting a sequence of actions over time while accounting for future states, rewards, and uncertainty. In Planning and Decision Making, the focus is on the analysis, design, implementation, interpretation, or evaluation of sequential decision making within Artificial Intelligence, particularly where the Planning and Decision Making module establishes its technical context.', 'SSD_COURSE_025_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M5_S1', 'learning paradigms', '1', 'learning paradigms: Major ways an AI system learns from data or interaction, including supervised, unsupervised, self-supervised, and reinforcement learning. In Machine Learning Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of learning paradigms within Artificial Intelligence, particularly where the Machine Learning Foundations module establishes its technical context.', 'SSD_COURSE_025_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M5_S2', 'hypothesis spaces', '2', 'hypothesis spaces refers to the set of candidate functions or models that a learning algorithm can select from. In Machine Learning Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of hypothesis spaces within Artificial Intelligence, particularly where the Machine Learning Foundations module establishes its technical context.', 'SSD_COURSE_025_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M5_S3', 'feature representations', '3', 'feature representations: Ways of encoding raw data as measurable variables that an AI model can use for learning or prediction. In Machine Learning Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of feature representations within Artificial Intelligence, particularly where the Machine Learning Foundations module establishes its technical context.', 'SSD_COURSE_025_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M5_S4', 'generalization', '4', 'generalization refers to the ability of a trained model to perform well on previously unseen data. In Machine Learning Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of generalization within Artificial Intelligence, particularly where the Machine Learning Foundations module establishes its technical context.', 'SSD_COURSE_025_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M5_S5', 'bias-variance', '5', 'bias-variance refers to the trade-off between systematic model error and sensitivity to training-data variation. In Machine Learning Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of bias-variance within Artificial Intelligence, particularly where the Machine Learning Foundations module establishes its technical context.', 'SSD_COURSE_025_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_025_M5_S6', 'learning pipelines', '6', 'learning pipelines: learning pipelines in Artificial Intelligence concerns ordered data, training, validation, packaging, and deployment stages that make machine-learning workflows reproducible and operational. In Machine Learning Foundations, the focus is on the analysis, design, implementation, interpretation, or evaluation of learning pipelines within Artificial Intelligence, particularly where the Machine Learning Foundations module establishes its technical context.', 'SSD_COURSE_025_M5_S6', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;